import { Router, Request, Response } from "express";
import { CreateTaskUseCase } from "../application/CreateTaskUseCase";
import { AssignTaskUseCase } from "../application/AssignTaskUseCase";
import { ListTasksUseCase } from "../application/ListTasksUseCase";
import { MarkTaskDoneUseCase } from "../application/MarkTaskDoneUseCase";
import { ITaskRepository } from "../domain/ITaskRepository";
import { IProjectRepository } from "../domain/IProjectRepository";
import { IUserRepository } from "../domain/IUserRepository";

export class TaskController {
  private router: Router;
  private createTaskUseCase: CreateTaskUseCase;
  private assignTaskUseCase: AssignTaskUseCase;
  private listTasksUseCase: ListTasksUseCase;
  private markTaskDoneUseCase: MarkTaskDoneUseCase;

  constructor(
    taskRepository: ITaskRepository,
    projectRepository: IProjectRepository,
    userRepository: IUserRepository,
  ) {
    this.router = Router();
    this.createTaskUseCase = new CreateTaskUseCase(
      taskRepository,
      projectRepository,
    );
    this.assignTaskUseCase = new AssignTaskUseCase(
      taskRepository,
      userRepository,
    );
    this.listTasksUseCase = new ListTasksUseCase(
      taskRepository,
      projectRepository,
    );
    this.markTaskDoneUseCase = new MarkTaskDoneUseCase(taskRepository);
    this.setupRoutes();
  }

  private setupRoutes(): void {
    this.router.post(
      "/projects/:projectId/tasks",
      (req: Request, res: Response) => {
        try {
          const projectId = String(req.params.projectId);
          const { title, description, dueDate } = req.body as {
            title?: string;
            description?: string;
            dueDate?: string;
          };

          if (!title) {
            res.status(400).json({ error: "Title is required" });
            return;
          }

          const parsedDueDate = dueDate ? new Date(dueDate) : null;
          const task = this.createTaskUseCase.execute(
            projectId,
            title,
            description || "",
            parsedDueDate,
          );
          res.status(201).json(task);
        } catch (error) {
          const message = error instanceof Error ? error.message : "Unknown error";
          res.status(400).json({ error: message });
        }
      },
    );

    this.router.get(
      "/projects/:projectId/tasks",
      (req: Request, res: Response) => {
        try {
          const projectId = String(req.params.projectId);
          const { status, assigneeId } = req.query;
          const statusValue =
            typeof status === "string" ? status : undefined;
          const assigneeIdValue =
            typeof assigneeId === "string" ? assigneeId : undefined;
          const tasks = this.listTasksUseCase.execute(
            projectId,
            statusValue,
            assigneeIdValue,
          );
          res.json(tasks);
        } catch (error) {
          const message = error instanceof Error ? error.message : "Unknown error";
          res.status(400).json({ error: message });
        }
      },
    );

    this.router.patch("/tasks/:taskId/assign", (req: Request, res: Response) => {
      try {
        const taskId = String(req.params.taskId);
        const { userId } = req.body as { userId?: string };

        if (!userId) {
          res.status(400).json({ error: "User ID is required" });
          return;
        }

        const task = this.assignTaskUseCase.execute(taskId, userId);
        res.json(task);
      } catch (error) {
        const message = error instanceof Error ? error.message : "Unknown error";
        res.status(400).json({ error: message });
      }
    });

    this.router.patch("/tasks/:taskId/done", (req: Request, res: Response) => {
      try {
        const taskId = String(req.params.taskId);
        const task = this.markTaskDoneUseCase.execute(taskId);
        res.json(task);
      } catch (error) {
        const message = error instanceof Error ? error.message : "Unknown error";
        res.status(400).json({ error: message });
      }
    });
  }

  getRouter(): Router {
    return this.router;
  }
}

